import math
    import random
    import time

    LANGUAGE_WRAPPER = 'On a rectangular {rows}×{cols} grid, a white piece and a black piece are placed uniformly at random in distinct cells. The white moves first, then the black; both pieces move one cell per turn horizontally or vertically, and for each piece, horizontal and vertical moves must alternate forever. Additionally, white is constrained to begin with a horizontal move, while black is constrained to begin with a vertical move. The players cooperate, choosing directions on each move to try to meet as soon as possible while obeying the alternation rule. Let p = m/n in lowest terms be the probability that there exists a round t such that immediately after the black’s move in round t, the two pieces occupy the same cell. Find m.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose moderately large dimensions to avoid trivial cases and ensure nontrivial counting
# Retry to make sure rows, cols >= 3
for _ in range(100):
    rows = rng.randint(1000, 5000)
    cols = rng.randint(1000, 5000)
    if rows >= 3 and cols >= 3:
        return {'rows': rows, 'cols': cols}
# Fallback
return {'rows': 1001, 'cols': 1002}

    def verifier(assign):
# Validate domain constraints
rows = assign.get('rows')
cols = assign.get('cols')
if not isinstance(rows, int) or not isinstance(cols, int):
    # invalid types
    return (False, None)
if rows < 3 or cols < 3:
    # ensure nontrivial grid
    return (False, None)
# Counting framework:
# Cells are (x,y) with x in [1..rows], y in [1..cols].
# Let xe be number of even x, xo odd x; ye even y, yo odd y.
xe = rows // 2
xo = rows - xe
ye = cols // 2
yo = cols - ye
# S = count of cells with same parity on both coordinates (EE or OO)
S = xe * ye + xo * yo
# D = count of cells with different parity on coordinates (EO or OE)
D = xe * yo + xo * ye
total_cells = rows * cols
# Favorable ordered pairs of distinct cells are those where
# parity differences on x and y are equal (both 0 or both 1),
# which counts as: same-category pairs plus diagonal-opposite-category pairs.
# Compact formula: favorable = S^2 + D^2 - total_cells (exclude equal-cell cases)
favorable = S * S + D * D - total_cells
total_ordered_distinct = total_cells * (total_cells - 1)
# Reduce the fraction favorable / total_ordered_distinct to lowest terms.
# Compute gcd safely.
def gcd(a, b):
    while b:
        a, b = b, a % b
    return abs(a)
g = gcd(favorable, total_ordered_distinct)
m = favorable // g
# Return numerator
return (True, m)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

